import io


class MeteredFile(io.BufferedRandom):
    """Implement using a subclassing model."""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._read_bytes = 0
        self._read_ops = 0
        self._write_bytes = 0
        self._write_ops = 0

    def __enter__(self):
        # Call the superclass's __enter__ for any necessary setup (e.g., resource acquisition)
        # and then explicitly return self, as is typical for file-like objects
        # acting as context managers. This ensures the 'as' clause in a 'with' statement
        # receives the MeteredFile instance itself.
        super().__enter__()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        # Delegate to the superclass's __exit__ which handles closing the file
        # and propagation of exceptions.
        return super().__exit__(exc_type, exc_val, exc_tb)

    def __iter__(self):
        # File objects are their own iterators.
        return self

    def __next__(self):
        # Read a chunk using the metered read method.
        # If read() returns empty bytes, it indicates EOF, so stop iteration.
        # io.BufferedRandom is a binary stream, so iteration yields bytes chunks, not lines.
        chunk = self.read(io.DEFAULT_BUFFER_SIZE)
        if not chunk:
            raise StopIteration
        return chunk

    def read(self, size=-1):
        # Perform the actual read operation using the superclass method
        data = super().read(size)
        # Update statistics
        self._read_bytes += len(data)
        self._read_ops += 1
        return data

    @property
    def read_bytes(self):
        return self._read_bytes

    @property
    def read_ops(self):
        return self._read_ops

    def write(self, b):
        # Perform the actual write operation using the superclass method
        bytes_written = super().write(b)
        # Update statistics
        self._write_bytes += bytes_written
        self._write_ops += 1
        return bytes_written

    @property
    def write_bytes(self):
        return self._write_bytes

    @property
    def write_ops(self):
        return self._write_ops


